alter table public.profiles add column if not exists identity_status text not null default 'unverified' check(identity_status in ('unverified','pending','verified','suspended')); alter table public.profiles add column if not exists risk_score smallint not null default 0 check(risk_score between 0 and 100); alter table public.profiles add column if not exists last_security_review timestamptz;
create table if not exists public.profile_security_events(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, event_type text not null, risk_delta smallint not null default 0, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()); create index if not exists profile_security_events_user_idx on public.profile_security_events(user_id,created_at desc);
create table if not exists public.api_rate_limits(user_id uuid not null references auth.users(id) on delete cascade, bucket text not null, window_started timestamptz not null, request_count integer not null default 0, primary key(user_id,bucket,window_started));
alter table public.profile_security_events enable row level security; alter table public.api_rate_limits enable row level security;
drop policy if exists security_events_self on public.profile_security_events; create policy security_events_self on public.profile_security_events for select using(user_id=auth.uid());
drop policy if exists security_events_insert_self on public.profile_security_events; create policy security_events_insert_self on public.profile_security_events for insert with check(user_id=auth.uid());
create or replace function public.consume_rate_limit(p_bucket text,p_limit integer default 60,p_window_seconds integer default 60) returns boolean language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); started timestamptz:=to_timestamp(floor(extract(epoch from now())/p_window_seconds)*p_window_seconds); n integer; begin if uid is null then return false; end if; insert into public.api_rate_limits(user_id,bucket,window_started,request_count) values(uid,p_bucket,started,1) on conflict(user_id,bucket,window_started) do update set request_count=api_rate_limits.request_count+1 returning request_count into n; return n<=p_limit; end $$;
revoke all on function public.consume_rate_limit(text,integer,integer) from public; grant execute on function public.consume_rate_limit(text,integer,integer) to authenticated;
create or replace function public.protect_profile_identity() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_op='UPDATE' and auth.uid()=old.id then new.identity_status=old.identity_status; new.risk_score=old.risk_score; new.last_security_review=old.last_security_review; end if; return new; end $$;
drop trigger if exists protect_profile_identity on public.profiles; create trigger protect_profile_identity before update on public.profiles for each row execute function public.protect_profile_identity();
